use std::fs

fn parse_num(s: string) -> Option<int> {
    let mut neg = false
    let mut v: int = 0
    let mut count = 0
    let mut first = true
    for c in s.chars() {
        if first && c == '-' {
            neg = true
        } else if c >= '0' && c <= '9' {
            v = v * 10 + (c as int - '0' as int)
            count += 1
        } else {
            return None
        }
        first = false
    }
    if count == 0 {
        return None
    }
    if neg {
        Some(0 - v)
    } else {
        Some(v)
    }
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for tok in line.split(" ") {
        if tok.len() == 0 {
            continue
        }
        if tok == "+" || tok == "-" || tok == "*" || tok == "/" {
            if st.len() < 2 {
                return "error: underflow"
            }
            let b = st.pop() ?? 0
            let a = st.pop() ?? 0
            if tok == "+" {
                st.push(a + b)
            } else if tok == "-" {
                st.push(a - b)
            } else if tok == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
        } else {
            match parse_num(tok) {
                Some(n) => st.push(n),
                None => return "error: token",
            }
        }
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        println("${eval(t)}")
    }
}

